import heapq

def dijkstra(graph, src):
    dist = {node: float('inf') for node in graph}
    dist[src] = 0
    pq = [(0, src)]
    visited = set()

    while pq:
        d, u = heapq.heappop(pq)
        if u in visited:
            continue
        visited.add(u)
        for v, weight in graph[u].items():
            if v not in visited:
                new_dist = d + weight
                if new_dist < dist[v]:
                    dist[v] = new_dist
                    heapq.heappush(pq, (new_dist, v))

    return dist

def test_dijkstra():
    # Test 1: Simple graph
    graph = {
        'A': {'B': 1, 'C': 4},
        'B': {'C': 2, 'D': 5},
        'C': {'D': 1},
        'D': {}
    }
    result = dijkstra(graph, 'A')
    assert result == {'A': 0, 'B': 1, 'C': 3, 'D': 4}

    # Test 2: Single node
    graph = {'A': {}}
    result = dijkstra(graph, 'A')
    assert result == {'A': 0}

    # Test 3: Disconnected node
    graph = {
        'A': {'B': 1},
        'B': {},
        'C': {}
    }
    result = dijkstra(graph, 'A')
    assert result == {'A': 0, 'B': 1, 'C': float('inf')}

