        for p in parts:
            if p == '':
                nums.append(0)
            else:
                nums.append(int(p))
        return nums

    pa = parse(a)
    pb = parse(b)

    max_len = max(len(pa), len(pb))
    while len(pa) < max_len:
        pa.append(0)
    while len(pb) < max_len:
        pb.append(0)

    for x, y in zip(pa, pb):
        if x < y:
            return -1
        elif x > y:
            return 1
    return 0


